head.script:
scwin.gVar = {
    "cTooltip": "",
    "cTooltipFormatter": "",
    "cTooltipLocaleRef": "",
    "cUseLocale": "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > tooltipLocaleRef]<br/>클라이언트 다국어가 적용되었을 때 tooltip 속성의 툴팁에 표시할 텍스트의 Key 값을 설정합니다.",
    "validation" : [
        "useLocale=true 이고 tooltip 속성이 설정된 경우에 동작하여야 합니다.",
        "툴팁에 표시할 다국어 텍스트의 Key 값을 문자열로 설정할 수 있어야 합니다.",
        "설정한 Key 값이 JS 파일에 없다면 'global_undefined' 가 적용되어야 합니다.",
        "tooltip 속성을 설정하지 않으면 tooltipLocaleRef 속성은 무시되어야 합니다.",
        "tooltip, useLocale, tooltipLocaleRef 속성을 모두 설정하여 클라이언트 다국어가 적용되면 tooltip 속성값은 무시되어야 합니다.",
        "다국어 기능은 Key:Value 형식으로 데이터가 정의된 JS 파일에서 Key 값에 해당하는 Value 값을 찾아 툴팁에 반영하여야 합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (textarea 는 tooltipFormatter 미지원)
    let properties = {
        tooltip: scwin.gVar["cTooltip"],
        tooltipLocaleRef: scwin.gVar["cTooltipLocaleRef"],
        useLocale: scwin.gVar["cUseLocale"],
    };

    let cList = $c.gcm.createCList(properties);

    // textarea 생성 (target1_onclick 에서 툴팁 정보 출력)
    await $c.gcm.createBasicTextArea(cList, 'ev:onclick="scwin.target1_onclick"');

    // textarea 가 지원하지 않는 옵션은 비활성화
    wf_sample.getObj("con_tooltipFormatter").setDisabled(true);
}
